mapper.update:
update tb_pathological_indicator
indicator_name = #{indicatorName}, update_by = #{updateBy}, annotation_category_total = (select count(*)from tb_pathological_indicator_category where indicator_id=#{indicatorId} and del_flag=0), project_total =(select count(*) from tb_project where indicator_id=#{indicatorId} and del_flag=0), update_time = sysdate()
where indicator_id = #{indicatorId}

update tb_pathological_indicator
set del_flag=1
where indicator_id = #{indicatorId}

mapper.select:
select *
from tb_pathological_indicator
where indicator_id!=#{indicatorId}
  and indicator_name=#{indicatorName}

select count(*)
from tb_special
where del_flag!=2 and indicator_id=#{indicatorId}
